package nl.slimov.app;
import org.json.*;
/** Defensive boundary for NS responses. A service number is never a vehicle number. */
public final class TrainApi {
 public static JSONArray positions(Object response)throws Exception{Object data=response;if(data instanceof JSONObject)data=((JSONObject)data).opt("payload");if(data==null)data=response;JSONArray rows=data instanceof JSONArray?(JSONArray)data:data instanceof JSONObject?((JSONObject)data).optJSONArray("treinen"):null;if(rows==null&&data instanceof JSONObject)rows=((JSONObject)data).optJSONArray("vehicles");JSONArray result=new JSONArray();if(rows==null)throw new Exception("NS antwoordformaat niet herkend: treinlijst ontbreekt");for(int i=0;i<rows.length();i++){JSONObject p=rows.optJSONObject(i);if(p==null)continue;double lat=p.optDouble("lat",Double.NaN),lon=p.optDouble("lng",p.optDouble("lon",Double.NaN));String number=p.optString("ritId",p.optString("treinNummer",p.optString("ritnummer","")));if(!number.matches("[0-9]{1,6}"))number=p.optString("treinNummer",p.optString("ritnummer",""));if(!number.matches("[0-9]{1,6}")||!Double.isFinite(lat)||!Double.isFinite(lon)||lat<50||lat>54||lon<3||lon>8)continue;JSONObject v=new JSONObject().put("id","ns:"+number).put("nsNumber",number).put("lat",lat).put("lon",lon).put("timestamp",System.currentTimeMillis()/1000).put("receivedAt",System.currentTimeMillis()/1000).put("positionTimeKnown",false).put("number","").put("line",p.optString("type","Trein")+" "+number).put("routeName",p.optString("vervoerder","Vervoerder niet doorgegeven")+" · rit "+number).put("agency",p.optString("vervoerder","")).put("owner","NSAPI").put("routeType",2).put("route","").put("direction",-1);if(p.has("richting"))v.put("bearing",p.optDouble("richting"));if(p.has("snelheid"))v.put("speed",p.optDouble("snelheid")/3.6);String timestamp=p.optString("timestamp",p.optString("tijdstip",""));try{v.put("timestamp",java.time.Instant.parse(timestamp).getEpochSecond()).put("positionTimeKnown",true);}catch(Exception ignored){}result.put(v);}return result;}
}
